_SRC['notify'] = (
    '"""Benachrichtigung bei neuen/verschwundenen Ger\xe4ten per Webhook (Teams-Workflow, Slack, Mattermo'
    'st, ntfy \u2026)."""\nimport json\nimport ssl\nimport urllib.request\n\nfrom .topology import TYPES\n'
    '\n\ndef build_message(topo):\n    diff = topo.get("diff") or {}\n    nodes = {n["id"]: n for n in to'
    'po["nodes"]}\n    new = [nodes[i] for i in diff.get("new", []) if i in nodes]\n    gone = diff.get("'
    'gone", [])\n    if not new and not gone:\n        return None\n\n    def line(n):\n        t = TYPES'
    '.get(n.get("type"), TYPES["unknown"])[0]\n        extra = " \xb7 ".join(x for x in (n.get("vendor"),'
    ' n.get("mac"), n.get("switch_port")) if x)\n        return f"{n.get(\'name\') or n.get(\'ip\')} ({n.'
    'get(\'ip\')}) \u2013 {t}" + (f" \xb7 {extra}" if extra else "")\n    title = f"NetzTopo: {len(new)} '
    'neue{\'s\' if len(new) == 1 else \'\'} Ger\xe4t{\'e\' if len(new) != 1 else \'\'}" + \\\n           '
    ' (f", {len(gone)} verschwunden" if gone else "")\n    lines = [("\U0001f195 " + line(n)) for n in ne'
    'w[:25]] + [("\u274c " + line(g)) for g in gone[:10]]\n    return title, lines\n\n\ndef send(url, top'
    'o, log=print, timeout=10):\n    msg = build_message(topo)\n    if not msg or not url:\n        retur'
    'n False\n    title, lines = msg\n    text = title + "\\n" + "\\n".join(lines)\n    if "ntfy" in url:'
    '\n        body, ctype = text.encode(), "text/plain; charset=utf-8"\n    else:\n        card = {"type'
    '": "AdaptiveCard", "$schema": "http://adaptivecards.io/schemas/adaptive-card.json", "version": "1.4"'
    ',\n                "body": [{"type": "TextBlock", "text": title, "weight": "Bolder", "size": "Medium'
    '", "wrap": True}] +\n                        [{"type": "TextBlock", "text": ln, "wrap": True, "spaci'
    'ng": "Small"} for ln in lines]}\n        body = json.dumps({"type": "message", "text": text,\n      '
    '                     "attachments": [{"contentType": "application/vnd.microsoft.card.adaptive", "con'
    'tent": card}]}).encode()\n        ctype = "application/json"\n    req = urllib.request.Request(url, '
    'data=body, method="POST", headers={"Content-Type": ctype})\n    try:\n        with urllib.request.ur'
    'lopen(req, timeout=timeout, context=ssl.create_default_context()) as r:\n            ok = 200 <= r.s'
    'tatus < 300\n    except Exception as e:  # noqa\n        log(f"\u26a0 Benachrichtigung fehlgeschlage'
    'n: {e}")\n        return False\n    log(f"Benachrichtigung gesendet: {title}")\n    return ok\n'
)

