    '     cands += [k for k in adj[roots[0]] if k not in cands]\n    res, spof = {}, []\n    for c in can'
    'ds:\n        lost = sorted(base - reach(c) - {c}, key=lambda i: _ipkey(nodes[i].get("ip")))\n       '
    ' if not lost:\n            continue\n        res[c] = lost\n        real = [nodes[i] for i in lost i'
    'f not nodes[i].get("virtual_node") and nodes[i].get("type") != "internet"]\n        risk = sum(WEIGH'
    'T.get(n.get("type"), 1) for n in real)\n        crit = [_name(n) for n in real if n.get("type") in C'
    'RITICAL][:8]\n        spof.append({"id": c, "name": _name(nodes[c]), "type": nodes[c].get("type"), "'
    'count": len(real),\n                     "risk": risk, "mix": _mix(real), "critical": crit})\n    sp'
    'of.sort(key=lambda s: (-s["risk"], -s["count"]))\n    return {"map": res, "spof": spof[:25], "root":'
    ' roots[0]}\n\n\n# ------------------------------------------------------------------ Sicherheit\n\nd'
    'ef _cert_days(valid_to):\n    if not valid_to:\n        return None\n    try:\n        import ssl\n '
    '       return int((ssl.cert_time_to_seconds(valid_to) - time.time()) // 86400)\n    except (ValueErr'
    'or, TypeError):\n        return None\n\n\ndef _ssh_old(banner):\n    b = str(banner or "")\n    if b'
    '.startswith("SSH-1."):\n        return "hoch", "SSH Version 1 (unsicher seit 20 Jahren)"\n    m = re'
    '.search(r"OpenSSH_(\\d+)\\.(\\d+)", b)\n    if m and (int(m.group(1)), int(m.group(2))) < (7, 4):\n '
    '       return "mittel", f"OpenSSH {m.group(1)}.{m.group(2)} ist veraltet"\n    m = re.search(r"dropb'
