    '(T[n.type]||T.unknown)[0] + " " + n.type).includes(v);\n      case "port": case "dienst": return Obj'
    'ect.keys(n.ports||{}).includes(v) || Object.values(n.ports||{}).some(x => low(x).includes(v));\n    '
    '  case "hersteller": case "vendor": return low(n.vendor).includes(v) || low(n.snmp_vendor).includes('
    'v);\n      case "switch": return low(n.switch_port).includes(v);\n      case "ip": return ipMatch(n,'
    ' v);\n      case "mac": return low(n.mac).replace(/[^0-9a-f]/g, "").startsWith(v.replace(/[^0-9a-f]/'
    'g, ""));\n      case "name": return low([n.name, n.dns, n.netbios].join(" ")).includes(v);\n      ca'
    'se "os": return low(n.os).includes(v);\n      case "schrank": return low(n.schrank).includes(v);\n  '
    '    case "zuverl": case "conf": return low(n.confidence).startsWith(v);\n    }\n  }\n  switch (t) {\n'
    '    case "neu": return !!n.is_new;\n    case "offline": return !!n.offline;\n    case "online": retu'
