    ' ?? "") > (y ?? "") ? sortDir : (x ?? "") < (y ?? "") ? -sortDir : 0;\n  });\n  document.getElementB'
    'yId("table").innerHTML = `<table><thead><tr>${COLS.map(([k,l]) => `<th onclick="sortBy(\'${k}\')">${'
